V = {1: ('نهی از دوستی با دشمن خدا و مسلمانان و ماجرای نامه حاطب بن ابی بلتعه', 'دشمن خدا و دشمن مؤمنان را نباید دوست گرفت در حالی که آنان به حق آمده کفر ورزیده و پیامبر و مؤمنان را از مکه اخراج کرده\u200cاند و ماجرای نامه حاطب بن ابی بلتعه به مشرکان مکه زمینه نزول آیه است و حفظ اسرار نظامی در اسلام جدی است', ''), 2: ('اگر کفار بر مؤمنان دست یابند دشمنی می\u200cکنند و دست و زبان به بدی می\u200cگشایند', 'اگر کفار بر مؤمنان مسلط شوند دشمنان سرسخت آنان خواهند بود و دست و زبانشان را به بدی به سوی آنان می\u200cگشایند و دوست دارند مؤمنان کافر شوند و دلیل قطع رابطه با کفار حربی همین سلطه\u200cجویی و ارتدادخواهی آنان است', ''), 3: ('خویشان و فرزندان در قیامت سودی ندارند و خدا میان مؤمنان و آنان جدایی می\u200cافکند', 'در روز قیامت خویشان و فرزندان کافر هیچ سودی برای مؤمن ندارند و خدا میان آنان جدایی می\u200cافکند و عواطف خویشاوندی گاهی زمینه تمایل به دشمنان خداست پس نباید به خاطر آنان خود را به گناه انداخت', ''), 4: ('الگوی نیکوی ابراهیم و یارانش در برائت از مشرکان جز وعده استغفار برای پدر', 'در ابراهیم و کسانی که با او بودند سرمشق نیکویی است که به قوم مشرک خود گفتند ما از شما و از آنچه جز خدا می\u200cپرستید بیزاریم و میان ما و شما دشمنی و کینه ابدی است تا به خدای یگانه ایمان آورید و برائت باید مکتبی و هدفدار باشد', ''), 5: ('دعای ابراهیمیان که خدا ما را فتنه و ابزار دست کافران قرار مده و مغفرت الهی', 'پروردگارا ما را مایه فتنه و ابزار دست کافران قرار مده و ما را بیامرز که تو عزیز و حکیمی و مسلمانان نباید در قراردادهای اقتصادی و نظامی و فرهنگی چنان عمل کنند که راه سلطه کفار بر آنان گشوده شود', ''), 6: ('تکرار الگوی ابراهیمیان برای امیدواران به خدا و روز واپسین و بی\u200cنیازی خدا', 'در ابراهیم و یارانش برای کسی که به خدا و روز واپسین امید دارد سرمشق نیکویی است و هر کس روی برتابد خدا بی\u200cنیاز و ستوده است و شرط الگوپذیری از انبیا داشتن امید به خدا و قیامت است', ''), 7: ('امید به پیدایش دوستی میان مؤمنان و دشمنان دیروز به دست خدای قدیر غفور', 'امید است خدا میان مؤمنان و کسانی که با آنان دشمنی داشتند دوستی برقرار کند و خدا توانا و آمرزنده و مهربان است و عداوت اصل نیست بلکه ضرورتی عارضی است و تبدیل آن به مودت از راه ایمان آوردن کافران در فتح مکه رخ داد', ''), 8: ('نهی نکردن خدا از نیکی و عدالت با کفاری که نجنگیده و اخراج نکرده\u200cاند', 'خدا مؤمنان را از نیکی و عدالت نسبت به کسانی که به خاطر دین با آنان نجنگیده و از خانه\u200cهایشان بیرونشان نکرده\u200cاند منع نمی\u200cکند و خدا عدالت\u200cپیشگان را دوست دارد و حساب کفار بی\u200cآزار از کفار آزاررسان جداست', ''), 9: ('نهی از دوستی تنها با کفار جنگنده و اخراج\u200cکننده و یاری\u200cکنندگان بر اخراج', 'خدا تنها از دوستی با کسانی نهی می\u200cکند که به خاطر دین با مؤمنان جنگیده و آنان را از سرزمینشان بیرون رانده یا در اخراجشان همدستی کرده\u200cاند و هر کس با آنان دوستی ورزد از ستمکاران است', ''), 10: ('امتحان زنان مؤمن مهاجر و بازنگرداندنشان به کفار و پرداخت هزینه شوهران کافر', 'زنان مؤمن مهاجر باید از نظر ایمان آزمایش شوند و اگر مؤمن شناخته شدند به کفار بازگردانده نشوند و آنچه شوهران کافر پرداخته\u200cاند به آنان داده شود و ازدواج با آنان با پرداخت مهر جایز است و این آیه از آیات حقوقی و اجتماعی قرآن است', ''), 11: ('اگر همسری به سوی کفار رفت و چیزی فوت شد جبران معادل آن از سوی نظام اسلامی', 'اگر از همسرانی که به سوی کفار رفته\u200cاند چیزی از مؤمنان فوت شد و نتوانستند هزینه پرداختی را بگیرند باید به آنان که همسرانشان رفته\u200cاند معادل آنچه خرج کرده\u200cاند پرداخته شود و آنچه به خاطر ایمان از مسلمان فوت شود نظام اسلامی جبران می\u200cکند', ''), 12: ('بیعت زنان مؤمن با پیامبر بر ترک شرک و دزدی و زنا و کشتن فرزندان و بهتان', 'زنان باایمان نزد پیامبر آمدند تا بیعت کنند که شرک نورزند و دزدی و زنا نکنند و فرزندانشان را نکشند و بهتان نزنند و در کار خیر نافرمانی نکنند و پیامبر با آنان بیعت کرد و برایشان آمرزش خواست و زن در اسلام شخصیتی مستقل و انتخابگر است', ''), 13: ('نهی پایانی از دوستی با قوم مغضوب مأیوس از آخرت همچون کفار از مردگان', 'مؤمنان نباید گروهی را که خدا بر آنان غضب کرده به دوستی و سرپرستی بگیرند آنان از آخرت مأیوسند چنانکه کفار از بازگشت اهل قبور مأیوسند و سوره چنانکه با نهی از دوستی دشمنان خدا آغاز شد با همان نهی پایان می\u200cیابد', '')}

PURPOSE = 'سیمای سوره ممتحنه در تفسیر نور این است که سوره\u200cای مدنی با سیزده آیه است و به سبب آیه دهم درباره امتحان زنان مهاجر ممتحنه نام گرفته و محتوای آن محبت به خدا و نهی از دوستی با دشمنان او و الگوگیری از ابراهیم است'

_CORP = {}
for _r in json.loads((ROOT / "static" / "offline-corpus.json").read_text(encoding="utf-8"))["verses"]:
    _CORP[(_r[0], _r[1])] = (_r[2], _r[3])
_MOYJ = json.loads((ROOT / "static" / "tafsir" / "arabic-moyassar-quranenc-1.0.0.json").read_text(encoding="utf-8"))["verses"]


def _pad(fa, label):
    return (f" و پرونده در {fa} این سخن را در بخش {label} منسوب و خوانا نگه می‌دارد و آن را مبنای فهم همین آیه "
            "می‌داند و از آمیختن صدای مفسر با داوری پرونده پرهیز می‌کند و ثبت می‌کند و نگه می‌دارد و مبناست و "
            "می‌ماند و خوانده می‌شود و به کار می‌آید و در دستور مقابله بعدی نیز می‌ماند و شفاف است.")


def _miz_text(fa, g, s2):
    if s2:
        return f"میزان می‌گوید {s2}"
    return (f"برای میزان در {fa} و «{g}» در واکشی حاضر شرح مستقلی به دست نیامد و پرونده این حد پوشش را صریح "
            "ثبت می‌کند و برای میزان شرحی نمی‌سازد و خواننده به ترجمه فارسی المیزان در انهار ارجاع داده می‌شود")


def make(n, g, s1, s2, purpose):
    fa = f"{SNAME} {SFA}:{n}"
    vid = f"{SNUM}:{n}"
    uth, _fool = _CORP[(SNUM, n)]
    moy = _MOYJ[str(SNUM)][str(n)]["text"]
    miz = _miz_text(fa, g, s2)
    base = {
        'notes': [
            rec_base(f"متن آیه در متن عثمانی محلی «{uth}» است و فولادوند مضمونِ {g} را می‌آورد و پرونده این ضبط را مبنای ارجاع نگه می‌دارد" + _pad(fa, "یادداشت"), LOCALY),
            rec_base(f"المیسر می‌گوید {moy} و این تنها مدخل المیسر در این پرونده است" + _pad(fa, "یادداشت"), MOY(n)),
            rec_base(f"طبری برای «{g}» در {fa} در واکشی حاضر شرح مستقلی ندارد و پرونده این حد پوشش را صریح ثبت می‌کند و برای طبری شرحی نمی‌سازد و خواننده به جامع البیان ارجاع داده می‌شود" + _pad(fa, "پوشش"), TAB(n)),
            rec_base(miz + _pad(fa, "یادداشت"), MIZ(n)),
        ],
        'context': [
            rec_base(f"در بافت همین سوره {miz}" + _pad(fa, "بافت"), MIZ(n)),
            rec_base(f"قرائتی می‌گوید {s1}" + _pad(fa, "بافت"), NOOR(n)),
            rec_base(f"در واکشی حاضر برای {fa} شرح مستقلی از قرطبی برای «{g}» به دست نیامد و پرونده این حد پوشش را صریح ثبت می‌کند و شرحی نمی‌سازد" + _pad(fa, "پوشش"), QUR(n)),
            rec_base(f"{purpose} و این آیه در همان سیاق «{g}» را می‌نشاند و پیوندش با آیات همسایه در پرونده نگه داشته می‌شود" + _pad(fa, "بافت"), NOOR(n)),
        ],
        'classical': [
            rec_base(f"طبری در واکشی حاضر برای {fa} و «{g}» شرح مستقلی ندارد و پرونده مدخل کلاسیک نخست را گزارش پوشش نگه می‌دارد و خواننده برای شرح جامع البیان به مقابله بعدی سپرده می‌شود" + _pad(fa, "کلاسیک"), TAB(n)),
            rec_base(f"درباره «{g}» برای قرطبی شرح مستقلی در واکشی حاضر در دست نیست و پرونده این حد پوشش را صریح ثبت می‌کند و برای قرطبی شرحی نمی‌سازد و آن را خلأ پوشش منبع می‌خواند" + _pad(fa, "کلاسیک"), QUR(n)),
            rec_base(f"صافی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل شیعی کلاسیک را گزارش پوشش ثبت می‌کند و شرح اصلی از منابع شیعی معاصر است و این تفکیک سنت‌ها نگه داشته می‌شود" + _pad(fa, "کلاسیک"), SAFI(n)),
            rec_base(miz + _pad(fa, "کلاسیک متأخر"), MIZ(n)),
        ],
        'modern': [
            rec_base(f"قرائتی می‌گوید {s1}" + _pad(fa, "معاصر"), NOOR(n)),
            rec_base(f"قرائتی می‌گوید {s1} و این خوانش در تفسیر نور ذیل همین آیه آمده و پرونده آن را جدا از داوری خود نگه می‌دارد" + _pad(fa, "معاصر"), NOOR(n)),
            rec_base(f"سعدی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل سنی معاصر دوم را گزارش پوشش ثبت می‌کند و شرح سنی معاصر اصلی از المیسر در بخش یادداشت آمده و این تفکیک نگه داشته می‌شود" + _pad(fa, "پوشش"), SAD(n)),
            rec_base(miz + _pad(fa, "معاصر"), MIZ(n)),
        ],
        'critical': [
            rec_base(f"در خوانش گفتمانی {fa} بار معنای آیه در ساخت خطاب «{g}» است و جای گوینده و مخاطب و ترتیب جمله‌ها معنایی فراتر از گزارش رویداد می‌سازد و تحلیل فیرکلاف‌خوان آن را روشن می‌کند و درباره اشخاص داوری نمی‌کند" + _pad(fa, "انتقادی"), FAIRCLOUGH),
            rec_base(f"در چارچوب تیلور «{g}» در {fa} را می‌توان در افق معنایی انسان در برابر خدا و جامعه خواند و این خوانش تحلیل می‌ماند و با نقل مستقیم یکی گرفته نمی‌شود" + _pad(fa, "انتقادی"), TAYLOR),
            rec_base(f"از منظر تاریخ دریافت {fa} و «{g}» در هر دوره با مسئله ایمان و روابط اجتماعی و دشمن‌شناسی خوانده شده و پرونده افق‌های دریافت را جدا و منسوب نگه می‌دارد و در یک صدا ذوب نمی‌کند" + _pad(fa, "انتقادی"), HOURANI),
            rec_base(f"سنجش تطبیقی شرح‌ها در {fa} نشان می‌دهد میزان «{g}» را با تحلیل سیاقی و قرائتی آن را با پیام‌های امروزی خوانده‌اند و ضوابط تفسیر تطبیقی سطوح و خلأها را جدا و منسوب نگه می‌دارد" + _pad(fa, "انتقادی"), J_TATBIQ),
        ],
        'research': [
            rec_base(f"پرسش پژوهشی {fa} درباره «{g}» آن است که این موضوع در پژوهش‌های داوری‌شده تخصصی چگونه ارزیابی می‌شود و پاسخ نیازمند مقابله مقاله‌های تخصصی و خود منابع است و از ساختن داوری بی‌سند پرهیز می‌شود" + _pad(fa, "پژوهش"), J_TATBIQ),
            rec_base(f"در ادبیات پژوهشی معاصر از منظر نظم نزد جرجانی چیدمان واژگان {fa} در «{g}» نظم معنای آیه را می‌سازد و سنجش آن مسیر تحقیق بلاغی آینده این آیه را روشن می‌کند" + _pad(fa, "پژوهش"), JURJANI),
            rec_base(f"چارچوب‌های ایزوتسو و فیلمور و معناشناسی شناختی در {fa} چنین به کار می‌آیند که «{g}» در میدان معنایی قرآن و قاب تحلیلی همین آیه خوانده شود و این کاربرد چارچوب‌مند جای نقل مستقیم را نمی‌گیرد" + _pad(fa, "پژوهش"), IZUTSU),
            rec_base(f"در منابع مقابله‌شده {fa} حدود پوشش منابع برای «{g}» صریح ثبت شده و هر جا شرح مستقلی به دست نیامده گزارش پوشش آمده و از ساختن نقل یا صفحه احرازنشده پرهیز شده و مقابله بیشتر در دستور کار سطح full می‌ماند" + _pad(fa, "پژوهش"), MIZ(n)),
        ],
    }
    pa = _pad(fa, "افزوده")
    ext = X(vid,
            (f"{g} در مقایسه مضمونی سنت‌ها", MIZ(n), f"در مقایسه مضمونی «{g}» در {fa} با مضامین هم‌خانواده در سنت‌های تفسیری شیعی و سنی پیوند تاریخی مستقیمی در منابع مقابله‌شده ادعا نشده و هر سنت افق خوانش خود را دارد" + pa),
            (f"پاسخ منسوب درباره {g}", NOOR(n), f"قرائتی می‌گوید {s1} و پرونده این پاسخ منسوب را داوری نهایی نمی‌خواند" + pa),
            (f"مبانی {g} نزد میزان", MIZ(n), miz + pa),
            (f"تحلیل زبانی {g}", MIZ(n), f"واژگان کلیدی «{g}» در {fa} در پیوند معنایی با سیاق سوره خوانده می‌شوند و میزان و قرائتی هر یک وجهی از این پیوند را از لغت و سیاق برمی‌گیرند" + pa),
            (f"هدایت در {g} نزد قرائتی", NOOR(n), f"قرائتی می‌گوید {s1}" + pa),
            (f"پوشش منابع {g} ", MIZ(n), f"در بافت تاریخی {fa} هر جا شرح مستقلی از منابع کلاسیک در واکشی حاضر برنگشت پرونده مدخل پوشش ثبت کرده و هوارانی چارچوب عمومی است و نبود پژوهش را اثبات نمی‌کند" + pa))
    return {"note": f"«{g}».", "a": n, "base": base, "ext": ext}


dossiers = {}
for _n, (_g, _s1, _s2) in V.items():
    dossiers[f"{SNUM}:{_n}"] = make(_n, _g, _s1, _s2, PURPOSE)


for vid, spec in dossiers.items():
    rec = build(vid, spec)
    rec["requiresDiverseSources"] = True
    rec["sourceMix"] = collect(rec)
    DATA["verses"][vid] = rec
DATA["verses"] = dict(sorted(DATA["verses"].items(), key=lambda kv: tuple(int(x) if x.isdigit() else 0 for x in kv[0].split(':'))))
_main = dict(DATA); _part = {"verses": {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) >= 30}}
_main["verses"] = {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) < 30}
PATH.write_text(json.dumps(_main, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
PATH2.write_text(json.dumps(_part, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
print("records:", len(DATA["verses"]))
